// Command gen_vectors writes the vectors in src/ that pin this package to other
// implementations of the same arithmetic:
//
//	golang.org/x/time/rate           a token bucket refilled continuously
//	github.com/juju/ratelimit        a token bucket refilled a tick at a time
//	github.com/cenkalti/backoff/v5   an exponential backoff, interval by interval
//	github.com/jpillora/backoff      the same schedule, computed from a power
//
// Every number in the generated files is what one of those answered for a call
// this package will be asked the same question about; the tests replay the calls
// and compare. Nothing in the data is written by hand, and nothing in it comes
// from this package.
//
// Regenerate from this directory, then let the formatter settle the file:
//
//	go run . -out ../../src
//	moon fmt
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

func main() {
	out := flag.String("out", "../../src", "directory the vector files are written to")
	flag.Parse()

	write(filepath.Join(*out, "limit_vectors_wbtest.mbt"), bucketVectors())
	write(filepath.Join(*out, "retry_vectors_wbtest.mbt"), backoffVectors())
}

func write(path, body string) {
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println("wrote", path)
}

const header = `// Copyright 2026 Leo Cheng
// SPDX-License-Identifier: Apache-2.0
//
// Generated by scripts/gen_vectors; do not edit by hand. Each row is one call
// this package is asked to answer again in the tests below it, with what another
// implementation answered.

`

// num writes a float64 as a MoonBit Double literal.
func num(v float64) string {
	s := strconv.FormatFloat(v, 'f', -1, 64)
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return s
}

func nanos(v int64) string { return strconv.FormatInt(v, 10) + "L" }

func bools(v []bool) string {
	parts := make([]string, len(v))
	for i, b := range v {
		if b {
			parts[i] = "true"
		} else {
			parts[i] = "false"
		}
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func nanos_list(v []int64) string {
	parts := make([]string, len(v))
	for i, n := range v {
		parts[i] = nanos(n)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func nums(v []float64) string {
	parts := make([]string, len(v))
	for i, n := range v {
		parts[i] = num(n)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// base is the instant every vector starts at. A whole day in keeps the zero
// value of a Go time out of any reference's first subtraction.
var base = time.Unix(1_700_000_000, 0)
